problem_statement:
Raw can't be updated
SVG in app.Raw() will not change after click the button twice.
```go

var Demo2 = func() func() app.UI {
	return func() app.UI {
		return &Button{}
	}
}()

type Button struct {
	app.Compo
	state bool
}

func (this *Button) Render() app.UI {
	const (
		raw1 = `<svg width="16px" height="16px" viewBox="0 0 1024 1024"><path d="M872 474H152c-4.4 0-8 3.6-8 8v60c0 4.4 3.6 8 8 8h720c4.4 0 8-3.6 8-8v-60c0-4.4-3.6-8-8-8z"/></svg>`
		raw2 = `<svg width="16px" height="16px" viewBox="0 0 1024 1024"><path d="M482 152h60q8 0 8 8v704q0 8-8 8h-60q-8 0-8-8V160q0-8 8-8Z"/><path d="M192 474h672q8 0 8 8v60q0 8-8 8H160q-8 0-8-8v-60q0-8 8-8Z"/></svg>`
	)
	return app.Button().Type("button").
		Body(
			app.If(this.state, func() app.UI {
				return app.Raw(raw1)
			}).Else(func() app.UI {
				return app.Raw(raw2)
			}),
			app.Span().Text(fmt.Sprintf("Click me [%v]", this.state)),
		).
		OnClick(func(ctx app.Context, e app.Event) {
			this.state = !this.state
			log.Log(this.state)
		})
}

```

