```
@maxence-charriere I tried that, and it looks like `app.Raw()` is kinda broken. It does not update and I think it should. Even if using `<div>1</div>` and `<div>2</div>` as the two raw strings and also when using same `app.Raw()` with switching the strings or two different `app.Raw()` as the original example.

@gepengscu We actually avoid using `app.Raw()` in our projects. You can solve that by using custom elements for the SVG like so:

```go
app.Button().Type("button").
	Body(
		app.If(uc.state, func() app.UI {
			return app.Elem("svg").XMLNS("http://www.w3.org/2000/svg").
				Attr("height", "16px").
				Attr("width", "16px").
				Attr("viewBox", "0 0 1024 1024").
				Body(
					app.ElemSelfClosing("path").XMLNS("http://www.w3.org/2000/svg").
						Attr("d", "M872 474H152c-4.4 0-8 3.6-8 8v60c0 4.4 3.6 8 8 8h720c4.4 0 8-3.6 8-8v-60c0-4.4-3.6-8-8-8z"),
				)
		}).Else(func() app.UI {
			return app.Elem("svg").XMLNS("http://www.w3.org/2000/svg").
				Attr("height", "16px").
				Attr("width", "16px").
				Attr("viewBox", "0 0 1024 1024").
				Body(
					app.ElemSelfClosing("path").XMLNS("http://www.w3.org/2000/svg").
						Attr("d", "M482 152h60q8 0 8 8v704q0 8-8 8h-60q-8 0-8-8V160q0-8 8-8Z"),
					app.ElemSelfClosing("path").XMLNS("http://www.w3.org/2000/svg").
						Attr("d", "M192 474h672q8 0 8 8v60q0 8-8 8H160q-8 0-8-8v-60q0-8 8-8Z"),
				)
		}),
		app.Span().Text(fmt.Sprintf("Click me [%v]", uc.state)),
	).
	OnClick(func(ctx app.Context, e app.Event) {
		uc.state = !uc.state
		app.Log(uc.state)
	})
```
@oderwat @maxence-charriere  The raw.parent() is nil after raw mounted to DOM. Add ```newMount.setParent(parent) ``` in  nodeManager.updateRawHTML  of "node.go" can solve the problem.
```go

func (m nodeManager) updateRawHTML(ctx Context, v, new *raw) (UI, error) {
	if v.value == new.value {
		return v, nil
	}
	newMount, err := m.Mount(ctx, v.depth(), new)
	if err != nil {
		return nil, errors.New("mounting updated raw html failed").
			WithTag("type", reflect.TypeOf(v)).
			WithTag("depth", v.depth()).
			WithTag("raw-preview", previewText(v.value)).
			Wrap(err)
	}
	for parent := v.parent(); parent != nil; parent = parent.parent() {
		if parent, isHTML := parent.(HTML); isHTML {
			parent.JSValue().replaceChild(newMount, v)
			newMount.setParent(parent)   <----- set parent here
			break
		}
	}
	m.Dismount(v)
	return newMount, nil
}

```

